<?php

declare(strict_types=1);

namespace App\Recipes\Domain;

/**
 * @internal the stored form of an Ingredient inside a Recipe; only Recipe creates and reads it.
 *
 * It is an entity only because each ingredient is a row of its own. The surrogate id is
 * generated by the database, and the position keeps the order the ingredients were given in.
 *
 * Not final: Doctrine generates a lazy-loading proxy for every entity.
 */
class RecipeIngredient
{
    private ?int $id = null;

    public function __construct(
        private readonly Recipe $recipe,
        private readonly ProductId $productId,
        private readonly Quantity $quantity,
        private readonly int $position,
    ) {
    }

    public function position(): int
    {
        return $this->position;
    }

    public function toIngredient(): Ingredient
    {
        return new Ingredient($this->productId, $this->quantity);
    }
}
